/**
 * The two framings the terminal pages use. A tile scene zooms in on the
 * top-left session of a 1440 x 900 window (2 x 2 grid, the homepage's 86
 * column captures), so one terminal fills the card. A window scene shows a
 * whole 1080 x 680 window, the narrowest the app keeps its tools inline at,
 * for what covers the canvas (the drop overlay, a dialog); its 2 x 2 grid
 * runs the 65 column captures that fit its tiles.
 */
import type { CSSProperties, ReactNode } from "react";
import type { BackdropScene } from "../../home/Backdrop";
import { Shot } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, SessionTile, WIN_SIZE, type Box, type SessionId } from "../../home/Scenes";
import type { CaptureId } from "../../home/captures";

const GRID_2X2: CSSProperties = { gridTemplateColumns: "1fr 1fr", gridTemplateRows: "1fr 1fr" };
const ORDER: SessionId[] = ["api", "web", "release", "docs"];

/* ------------------------------------------------------------------ tile -- */

/* The card ends in the grid's gaps, so no tile is cut: its right edge in the
   column gap, its bottom edge in the row gap. The first column is widened to
   748px (the app's columns resize) so that gap, x 758..768, also falls
   between two of the top bar's centred workspace tabs (fieldnotes ends at
   762, personal starts at 764): the edge at 763 cuts neither. The grid area
   is x 10..1430, y 52..890; two equal rows put the row gap at y 466..476. */
const COLUMN = 748;
const SPLIT_X = 10 + COLUMN + 5;
const ROW_GAP_Y = 471;
export const TILE_BOX: Box = { left: 16, top: 24, ...WIN_SIZE };
export const TILE_FRAME = { width: TILE_BOX.left + SPLIT_X, height: TILE_BOX.top + ROW_GAP_Y };
const TILE_GRID: CSSProperties = { gridTemplateColumns: `${COLUMN}px 1fr`, gridTemplateRows: "1fr 1fr" };
export const WIDE: Record<SessionId, CaptureId> = { api: "api-86", web: "web-86", release: "release-86", docs: "docs-86" };

/**
 * A window framed on its first tile, `tile` (running `session`); the other
 * sessions fill the rest of the grid. `overlay` goes over the window, in a
 * Viewport of TILE_BOX's size.
 */
export function TileShot({ backdrop, session, tile, overlay }: { backdrop: BackdropScene; session: SessionId; tile: ReactNode; overlay?: ReactNode }) {
  const rest = ORDER.filter((id) => id !== session);
  return (
    <Shot id={backdrop} width={TILE_FRAME.width} height={TILE_FRAME.height}>
      <AppWindow box={TILE_BOX}>
        <ActiveCanvas
          style={TILE_GRID}
          tiles={[tile, ...rest.map((id, i) => <SessionTile key={id} id={id} capture={WIDE[id]} kbd={`⌘${i + 2}`} />)]}
        />
        {overlay}
      </AppWindow>
    </Shot>
  );
}

/* ---------------------------------------------------------------- window -- */

export const WINDOW_FRAME = { width: 1120, height: 720 };
export const WINDOW_BOX: Box = { left: 20, top: 20, width: 1080, height: 680 };
/** The canvas under the 42px top bar, in window coordinates (Canvas.tsx, canvasBox). */
export const WINDOW_CANVAS = { left: 0, top: 42, width: WINDOW_BOX.width, height: WINDOW_BOX.height - 42 };
export const NARROW: Record<SessionId, CaptureId> = { api: "api-65", web: "web-65", release: "release-65", docs: "docs-65" };

/** The whole window with its four sessions, `active` the focused one, and `overlay` over it. */
export function WindowShot({ backdrop, active = 0, overlay }: { backdrop: BackdropScene; active?: number; overlay: ReactNode }) {
  return (
    <Shot id={backdrop} width={WINDOW_FRAME.width} height={WINDOW_FRAME.height}>
      <AppWindow box={WINDOW_BOX}>
        <ActiveCanvas
          initial={active}
          style={GRID_2X2}
          tiles={ORDER.map((id, i) => <SessionTile key={id} id={id} capture={NARROW[id]} kbd={`⌘${i + 1}`} />)}
        />
        {overlay}
      </AppWindow>
    </Shot>
  );
}
